// Badge Completion Across the Cohort
// CANVAS_HEIGHT: 540
// Generated by scripts/build-chartjs-sim.py from scripts/sim-charts/progress-dashboard-explorer.json.
// Edit the data file and regenerate rather than editing this file by hand.

const chartData = {
    "labels": [
        "First Program",
        "Loops",
        "Variables",
        "Functions",
        "Sensors",
        "Debugging"
    ],
    "datasets": [
        {
            "label": "Students who earned the badge",
            "data": [
                14,
                12,
                9,
                6,
                4,
                3
            ],
            "backgroundColor": "#4A90D9"
        }
    ]
};

const chartOptions = {
    "responsive": true,
    "maintainAspectRatio": false,
    "plugins": {
        "legend": {
            "position": "top",
            "align": "end",
            "labels": {
                "boxWidth": 14,
                "font": {
                    "size": 12
                }
            },
            "display": false
        },
        "tooltip": {
            "titleFont": {
                "size": 13
            },
            "bodyFont": {
                "size": 13
            }
        }
    },
    "scales": {
        "x": {
            "ticks": {
                "font": {
                    "size": 11
                },
                "maxRotation": 30
            }
        },
        "y": {
            "beginAtZero": true,
            "ticks": {
                "font": {
                    "size": 12
                }
            },
            "title": {
                "display": true,
                "text": "Students who earned it",
                "font": {
                    "size": 13
                }
            }
        }
    }
};

const ctx = document.getElementById('chart');
const chart = new Chart(ctx, {
    type: "bar",
    data: chartData,
    options: chartOptions
});

// Checkbox controls mirror the legend, so a series can be toggled without
// knowing that clicking a legend entry does that.
document.querySelectorAll('[data-dataset]').forEach(el => {
    el.addEventListener('change', () => {
        const i = parseInt(el.dataset.dataset, 10);
        chart.setDatasetVisibility(i, el.checked);
        chart.update();
    });
    // apply the initial state declared in the data file
    const i = parseInt(el.dataset.dataset, 10);
    chart.setDatasetVisibility(i, el.checked);
});
chart.update();

// Dropdown controls call onControl, and buttons call onAction. A sim defines
// whichever it needs in its extraJs block; both are optional.
document.querySelectorAll('select[data-control]').forEach(el => {
    el.addEventListener('change', () => {
        if (typeof onControl === 'function') onControl(el.dataset.control, el.value);
    });
});

document.querySelectorAll('button[data-action]').forEach(el => {
    el.addEventListener('click', () => {
        if (typeof onAction === 'function') onAction(el.dataset.action);
    });
});


// Mock cohort data, initials only -- the same minimal-identifiability habit the
// chapter argues for. Each student has an explicit set of earned badges rather
// than a count: students genuinely do take badges out of order, and a strict
// ladder would force the last badge to be every cohort's bottleneck, which
// would make the cohort filter pointless.
const BADGES = ['First Program', 'Loops', 'Variables', 'Functions', 'Sensors', 'Debugging'];
const COHORTS = {
    'Tuesday Group': {
        'AB': ['First Program', 'Loops', 'Variables', 'Functions', 'Debugging'],
        'CD': ['First Program', 'Loops', 'Variables', 'Debugging'],
        'EF': ['First Program', 'Loops', 'Variables'],
        'GH': ['First Program', 'Loops', 'Debugging'],
        'JK': ['First Program', 'Loops'],
        'LM': ['First Program', 'Loops', 'Variables', 'Functions', 'Debugging'],
        'NP': ['First Program', 'Loops', 'Variables'],
        'QR': ['First Program', 'Sensors']
    },
    'Thursday Group': {
        'ST': ['First Program', 'Loops', 'Variables', 'Sensors', 'Functions'],
        'UV': ['First Program', 'Loops', 'Sensors'],
        'WX': ['First Program', 'Loops', 'Variables', 'Sensors', 'Functions'],
        'YZ': ['First Program', 'Sensors', 'Debugging'],
        'AC': ['First Program', 'Loops', 'Variables', 'Sensors'],
        'BD': ['First Program', 'Loops', 'Sensors'],
        'CE': ['First Program', 'Loops', 'Variables', 'Sensors']
    }
};

function countsFor(cohort) {
    const groups = cohort === 'All' ? Object.values(COHORTS) : [COHORTS[cohort]];
    return BADGES.map(badge =>
        groups.reduce((total, g) =>
            total + Object.values(g).filter(list => list.includes(badge)).length, 0));
}

let currentCohort = 'All';
let currentSort = 'Highest first';

function render() {
    const counts = countsFor(currentCohort);
    let rows = BADGES.map((b, i) => ({ badge: b, count: counts[i] }));
    if (currentSort === 'Highest first') rows.sort((a, b) => b.count - a.count);
    else if (currentSort === 'Lowest first') rows.sort((a, b) => a.count - b.count);
    chart.data.labels = rows.map(r => r.badge);
    chart.data.datasets[0].data = rows.map(r => r.count);
    chart.update();

    const low = rows.reduce((m, r) => r.count < m.count ? r : m, rows[0]);
    const who = currentCohort === 'All' ? 'the whole club' : currentCohort;
    const box = document.getElementById('ranking');
    if (box) {
        const tally = low.count === 0 ? 'no students have'
                    : low.count === 1 ? 'only 1 student has'
                    : 'only ' + low.count + ' students have';
        box.innerHTML = '<strong>Current bottleneck</strong><br>' + low.badge +
            ' - ' + tally + ' earned it in ' + who + '.';
    }
}

function onControl(id, value) {
    if (id === 'cohort') currentCohort = value;
    if (id === 'sort') currentSort = value;
    render();
}

function onAction(id) {
    if (id !== 'reset') return;
    currentCohort = 'All';
    currentSort = 'Highest first';
    document.querySelector('select[data-control="cohort"]').value = 'All';
    document.querySelector('select[data-control="sort"]').value = 'Highest first';
    render();
}

render();

